Lemma fit_short (fx : FPState) R M model LK Aw (n0 m : Z) :
  stok model LK Aw -> pfx M (o + 1) -> s = PM.VShort n0 -> n = n0 + m -> 1 <= m -> n <= 22 -> 0 <= n0 -> tg = 0 ->
